function getPostFullImageUrl($post) {
    $day = (int)($post['day'] ?? 1);
    if (!empty($post['imageUrl'])) {
        return 'https://banya-school.ru' . $post['imageUrl'];
    }
    if ($day >= 1 && $day <= 9) {
        return "https://banya-school.ru/images/post-{$day}.jpg";
    }
    return 'https://banya-school.ru/images/levels/level-1-hero.jpg';
}

function formatDzenHtml($rawText, $takeaway, $day, $imgUrl, $title) {
    $html = htmlspecialchars($rawText, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    $html = preg_replace('/\*\*([^*]+)\*\*/u', '<b>$1</b>', $html);
    $html = preg_replace('/\*([^*\n]+)\*/u', '<i>$1</i>', $html);
    $html = preg_replace('/\[([^\]]+)\]\((https?:\/\/[^\)]+)\)/u', '<a href="$2">$1</a>', $html);

    $safeTitle = htmlspecialchars($title, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    $out = '<figure><img src="' . $imgUrl . '" /><figcaption>' . $safeTitle . ' — Школа банного мастерства banya-school.ru</figcaption></figure>' . "\n";

    $paragraphs = preg_split('/\n\s*\n/u', trim($html));
    foreach ($paragraphs as $p) {
        $cleanP = nl2br(trim($p));
        if ($cleanP !== '') {
            $out .= "<p>{$cleanP}</p>\n";
        }
    }
    if (!empty($takeaway)) {
        $safeTakeaway = htmlspecialchars($takeaway, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $out .= "<blockquote><b>📌 Главный вывод Бати:</b> {$safeTakeaway}</blockquote>\n";
    }
    $out .= '<p><a href="https://banya-school.ru/?utm_source=dzen&amp;utm_campaign=day_' . (int)$day . '">🔥 Пройти бесплатный интерактивный симулятор русской печи и тренажер пармастера на banya-school.ru</a></p>';
    return $out;
}

